CREATE TABLE `autonomous_agent_runs` (`id` varchar(36) NOT NULL,`organizationId` varchar(36) NOT NULL,`userId` int NOT NULL,`locationId` varchar(36) NOT NULL,`goal` varchar(64) NOT NULL,`status` varchar(32) NOT NULL,`plannerType` varchar(32) NOT NULL,`llmProvider` varchar(32) NOT NULL,`llmModel` varchar(100) NOT NULL,`fallbackUsed` boolean NOT NULL DEFAULT false,`stepsUsed` int NOT NULL DEFAULT 0,`toolCallsUsed` int NOT NULL DEFAULT 0,`riskScore` int,`riskLevel` varchar(32),`result` json,`errorCode` varchar(64),`startedAt` timestamp NOT NULL DEFAULT (now()),`completedAt` timestamp,`createdAt` timestamp NOT NULL DEFAULT (now()),CONSTRAINT `autonomous_agent_runs_id` PRIMARY KEY(`id`));
CREATE INDEX `autonomous_runs_org_time_idx` ON `autonomous_agent_runs` (`organizationId`,`createdAt`);
CREATE INDEX `autonomous_runs_location_idx` ON `autonomous_agent_runs` (`locationId`);
CREATE TABLE `autonomous_agent_events` (`id` varchar(36) NOT NULL,`runId` varchar(36) NOT NULL,`organizationId` varchar(36) NOT NULL,`type` varchar(80) NOT NULL,`message` text NOT NULL,`metadata` json,`createdAt` timestamp NOT NULL DEFAULT (now()),CONSTRAINT `autonomous_agent_events_id` PRIMARY KEY(`id`));
CREATE INDEX `autonomous_events_run_idx` ON `autonomous_agent_events` (`runId`);
CREATE TABLE `autonomous_agent_tool_calls` (`id` varchar(36) NOT NULL,`runId` varchar(36) NOT NULL,`organizationId` varchar(36) NOT NULL,`toolName` varchar(96) NOT NULL,`status` varchar(32) NOT NULL,`durationMs` int NOT NULL,`inputJson` json,`outputSummary` json,`createdAt` timestamp NOT NULL DEFAULT (now()),CONSTRAINT `autonomous_agent_tool_calls_id` PRIMARY KEY(`id`));
CREATE INDEX `autonomous_tool_calls_run_idx` ON `autonomous_agent_tool_calls` (`runId`);
